void uf_union(int a, int b) {
    int ra = uf_find(a), rb = uf_find(b);
    if (ra == rb) return;
    if (uf[ra].rank < uf[rb].rank) {
        uf[ra].parent = rb;
    } else if (uf[ra].rank > uf[rb].rank) {
        uf[rb].parent = ra;
    } else {
        uf[rb].parent = ra;
        uf[ra].rank++;
    }
}

