#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1000000007LL

typedef long long ll;

typedef struct {
    int c;
    ll w;
    int id;
} Ball;

typedef struct {
    ll w;
    int pos;
} Item;

static int cmp_ball_w(const void *a, const void *b) {
    const Ball *x = (const Ball *)a;
    const Ball *y = (const Ball *)b;
    if (x->w < y->w) return -1;
    if (x->w > y->w) return 1;
    return x->id - y->id;
}

static int cmp_item_w(const void *a, const void *b) {
    const Item *x = (const Item *)a;
    const Item *y = (const Item *)b;
    if (x->w < y->w) return -1;
    if (x->w > y->w) return 1;
    return x->pos - y->pos;
}

static ll modpow(ll a, ll e) {
    ll r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N;
    ll X, Y;
    if (scanf("%d %lld %lld", &N, &X, &Y) != 3) return 0;

    Ball *balls = (Ball *)malloc(sizeof(Ball) * N);
    int *origColor = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) {
        scanf("%d %lld", &balls[i].c, &balls[i].w);
        balls[i].id = i;
        origColor[i] = balls[i].c;
    }

    /* Coordinate-compress colors */
    int *allc = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) allc[i] = balls[i].c;
    qsort(allc, N, sizeof(int), cmp_item_w); /* works for int? no */
    /* fix: use manual sort comparator for int */
    free(allc);

    /* sort balls by color value to compress */
    Ball *tmpByColor = (Ball *)malloc(sizeof(Ball) * N);
    memcpy(tmpByColor, balls, sizeof(Ball) * N);
    int cmp_ball_c(const void *a, const void *b) {
        const Ball *x = (const Ball *)a;
        const Ball *y = (const Ball *)b;
        if (x->c < y->c) return -1;
        if (x->c > y->c) return 1;
        return x->id - y->id;
    }
    qsort(tmpByColor, N, sizeof(Ball), cmp_ball_c);

    int m = 0;
    int *compColor = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) {
        if (i == 0 || tmpByColor[i].c != tmpByColor[i - 1].c) m++;
        compColor[tmpByColor[i].id] = m - 1;
    }
    free(tmpByColor);

    for (int i = 0; i < N; i++) balls[i].c = compColor[i];

    /* Build groups by compressed color */
    int *cntColor = (int *)calloc(m, sizeof(int));
    for (int i = 0; i < N; i++) cntColor[balls[i].c]++;

    int **positions = (int **)malloc(sizeof(int *) * m);
    ll **weights = (ll **)malloc(sizeof(ll *) * m);
    int *ptr = (int *)calloc(m, sizeof(int));
    for (int c = 0; c < m; c++) {
        positions[c] = (int *)malloc(sizeof(int) * cntColor[c]);
        weights[c] = (ll *)malloc(sizeof(ll) * cntColor[c]);
    }
    for (int i = 0; i < N; i++) {
        int c = balls[i].c;
        positions[c][ptr[c]] = i;
        weights[c][ptr[c]] = balls[i].w;
        ptr[c]++;
    }

    /* For each color, determine connected components under same-color swaps:
       weights sorted, edges between adjacent if sum <= X, thus components are intervals.
       For each original occurrence position, assign a local component id. */
    int *localComp = (int *)malloc(sizeof(int) * N);
    int *numCompPerColor = (int *)calloc(m, sizeof(int));

    for (int c = 0; c < m; c++) {
        int k = cntColor[c];
        Item *arr = (Item *)malloc(sizeof(Item) * k);
        for (int i = 0; i < k; i++) {
            arr[i].w = weights[c][i];
            arr[i].pos = positions[c][i];
        }
        qsort(arr, k, sizeof(Item), cmp_item_w);

        int comp = 0;
        for (int i = 0; i < k; i++) {
            if (i == 0 || arr[i - 1].w + arr[i].w > X) comp++;
            localComp[arr[i].pos] = comp - 1;
        }
        numCompPerColor[c] = comp;
        free(arr);
    }

    /* Build all same-color components as groups with minimum weight */
    int totalGroups = 0;
    for (int c = 0; c < m; c++) totalGroups += numCompPerColor[c];

    int *groupColor = (int *)malloc(sizeof(int) * totalGroups);
    ll *groupMinW = (ll *)malloc(sizeof(ll) * totalGroups);
    int *groupSize = (int *)calloc(totalGroups, sizeof(int));
    int *base = (int *)malloc(sizeof(int) * m);

    int acc = 0;
    for (int c = 0; c < m; c++) {
        base[c] = acc;
        for (int j = 0; j < numCompPerColor[c]; j++) {
            groupColor[acc + j] = c;
            groupMinW[acc + j] = (1LL << 62);
        }
        acc += numCompPerColor[c];
    }

    int *ballGroup = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) {
        int g = base[balls[i].c] + localComp[i];
        ballGroup[i] = g;
        groupSize[g]++;
        if (balls[i].w < groupMinW[g]) groupMinW[g] = balls[i].w;
    }

    /* Components among groups using different-color swaps:
       two groups connect if colors differ and minW[a]+minW[b] <= Y.
       After sorting by minW, for each prefix under threshold, all colors can mix.
       We process connected components by DSU over active groups with color compression inside segment.
    */
    Item *grp = (Item *)malloc(sizeof(Item) * totalGroups);
    for (int i = 0; i < totalGroups; i++) {
        grp[i].w = groupMinW[i];
        grp[i].pos = i;
    }
    qsort(grp, totalGroups, sizeof(Item), cmp_item_w);

    int *parent = (int *)malloc(sizeof(int) * totalGroups);
    int *sz = (int *)malloc(sizeof(int) * totalGroups);
    for (int i = 0; i < totalGroups; i++) parent[i] = i, sz[i] = 1;

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) { int t = a; a = b; b = t; }
        parent[b] = a;
        sz[a] += sz[b];
    }

    /* Key observation:
       In sorted order by min weight, if grp[l].w + grp[r].w <= Y, then every pair inside [l..r]
       with different colors is swappable enough to connect through the lightest compatible groups.
       We can merge consecutive sorted groups into segments where min + max <= Y.
       Inside each such segment, all groups become connected regardless of color restrictions
       except that same-color groups are already distinct and can still connect via another color
       if segment has at least two colors. This is enough because edges exist for all diff-color pairs
       satisfying threshold, and with the lightest group of another color paths exist.
    */

    int l = 0;
    while (l < totalGroups) {
        int r = l;
        while (r + 1 < totalGroups && grp[l].w + grp[r + 1].w <= Y) r++;

        if (r > l) {
            /* Unite all groups in [l..r] through representatives of different colors.
               Use first occurrence per color and one hub color if possible. */
            int segmentLen = r - l + 1;
            int *seenColor = (int *)malloc(sizeof(int) * segmentLen);
            int *seenGroup = (int *)malloc(sizeof(int) * segmentLen);
            int sc = 0;
            for (int i = l; i <= r; i++) {
                int g = grp[i].pos;
                int c = groupColor[g];
                int found = -1;
                for (int j = 0; j < sc; j++) {
                    if (seenColor[j] == c) { found = j; break; }
                }
                if (found == -1) {
                    seenColor[sc] = c;
                    seenGroup[sc] = g;
                    sc++;
                }
            }
            if (sc >= 2) {
                int hub = seenGroup[0];
                int hub2 = seenGroup[1];
                unite(hub, hub2);
                for (int j = 2; j < sc; j++) unite(hub, seenGroup[j]);
                int rootHub = find(hub);
                for (int i = l; i <= r; i++) {
                    int g = grp[i].pos;
                    if (groupColor[g] != groupColor[hub]) unite(rootHub, g);
                    else unite(hub2, g);
                }
            }
            free(seenColor);
            free(seenGroup);
        }
        l++;
    }

    /* Collect final connected components of groups */
    int *compIndex = (int *)malloc(sizeof(int) * totalGroups);
    for (int i = 0; i < totalGroups; i++) compIndex[i] = -1;

    ll *fact = (ll *)malloc(sizeof(ll) * (N + 1));
    ll *invfact = (ll *)malloc(sizeof(ll) * (N + 1));
    fact[0] = 1;
    for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
    invfact[N] = modpow(fact[N], MOD - 2);
    for (int i = N; i > 0; i--) invfact[i - 1] = invfact[i] * i % MOD;

    ll ans = 1;

    for (int i = 0; i < totalGroups; i++) {
        int r0 = find(i);
        if (compIndex[r0] != -1) continue;

        int total = 0;
        ll ways = 1;
        for (int j = 0; j < totalGroups; j++) {
            if (find(j) == r0) {
                total += groupSize[j];
                ways = ways * invfact[groupSize[j]] % MOD;
            }
        }
        ways = ways * fact[total] % MOD;
        ans = ans * ways % MOD;
        compIndex[r0] = 1;
    }

    printf("%lld\n", ans % MOD);

    return 0;
}

