using namespace std;
using int64 = long long;
const int MOD = 1e9 + 7;

struct DSU {
    vector<int> parent, sz;
    DSU(int n) {
        parent.resize(n);
        sz.resize(n, 1);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        while (parent[x] != x) parent[x] = parent[parent[x]], x = parent[x];
        return x;
    }
    void unite(int a, int b) {
        a = find(a), b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, X, Y;
    cin >> N >> X >> Y;
    vector<int> c(N), w(N);
    vector<vector<pair<int,int>>> colorBalls(N); // color -> (weight, index)
    for (int i = 0; i < N; i++) {
        cin >> c[i] >> w[i];
        c[i]--; // make 0-indexed
        colorBalls[c[i]].push_back({w[i], i});
    }

    DSU dsu(N);

    // Operation 1: same color
    for (int col = 0; col < N; col++) {
        auto &v = colorBalls[col];
        if (v.empty()) continue;
        sort(v.begin(), v.end());
        int lightest = v[0].second;
        for (size_t j = 1; j < v.size(); j++) {
            if (v[0].first + v[j].first <= X) {
                dsu.unite(lightest, v[j].second);
            }
        }
    }

    // Operation 2: different colors
    // find global lightest ball and per-color lightest
    int globalLightestIdx = min_element(w.begin(), w.end()) - w.begin();
    int globalLightestWeight = w[globalLightestIdx];

    vector<int> lightestPerColor(N, -1);
    for (int col = 0; col < N; col++) {
        if (colorBalls[col].empty()) continue;
        auto &v = colorBalls[col];
        int idx = min_element(v.begin(), v.end())->second;
        lightestPerColor[col] = idx;
    }

    // Connect global lightest to all others if sum <= Y
    for (int i = 0; i < N; i++) {
        if (i == globalLightestIdx) continue;
        if (c[i] != c[globalLightestIdx] && w[i] + globalLightestWeight <= Y) {
            dsu.unite(globalLightestIdx, i);
        }
    }

    // For each color, connect its lightest to others of different colors
    for (int col = 0; col < N; col++) {
        if (lightestPerColor[col] == -1) continue;
        int li = lightestPerColor[col];
        if (dsu.find(li) == dsu.find(globalLightestIdx)) continue; // already connected via global
        for (int i = 0; i < N; i++) {
            if (c[i] != col && w[i] + w[li] <= Y) {
                dsu.unite(li, i);
            }
        }
    }

    // Precompute factorials
    vector<int64> fact(N+1, 1), invfact(N+1, 1);
    for (int i = 1; i <= N; i++) fact[i] = fact[i-1] * i % MOD;
    auto modpow = [&](int64 a, int64 b) {
        int64 res = 1;
        while (b) {
            if (b & 1) res = res * a % MOD;
            a = a * a % MOD;
            b >>= 1;
        }
        return res;
    };
    invfact[N] = modpow(fact[N], MOD-2);
    for (int i = N; i >= 1; i--) invfact[i-1] = invfact[i] * i % MOD;

    // Group by component
    unordered_map<int, vector<int>> comps;
    for (int i = 0; i < N; i++) {
        comps[dsu.find(i)].push_back(i);
    }

    int64 ans = 1;
    for (auto &[root, members] : comps) {
        int sz = members.size();
        int64 ways = fact[sz];
        unordered_map<int,int> cntColor;
        for (int idx : members) cntColor[c[idx]]++;
        for (auto &[col, cnt] : cntColor) {
            ways = ways * invfact[cnt] % MOD;
        }
        ans = ans * ways % MOD;
    }

    cout << ans << "\n";
    return 0;
}

