        if(col!=c[gmin] && w[gmin]+w[idx]<=Y) unite(idx,gmin);
    }

    fact[0]=1; for(int i=1;i<=n;i++) fact[i]=fact[i-1]*i%MOD;
    auto inv=[&](long long a){long long r=1,b=MOD-2;while(b){if(b&1)r=r*a%MOD;a=a*a%MOD;b>>=1;}return r;};

    map<int,map<int,int>> comp_color; // component root -> color -> count
    map<int,int> comp_size;
    for(int i=0;i<n;i++){ comp_color[find(i)][c[i]]++; comp_size[find(i)]++; }

    long long ans=1;
    for(auto&[root,cc]:comp_color){
        ans=ans*fact[comp_size[root]]%MOD;
        for(auto&[col,cnt]:cc) ans=ans*inv(fact[cnt])%MOD;
    }
    printf("%lld\n",ans);
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

struct DSU {
    int n;
    vector<int> p, sz;
    DSU(int n = 0): n(n), p(n), sz(n,1) {
        iota(p.begin(), p.end(), 0);
    }
    int find(int x){
        if(p[x]==x) return x;
        return p[x]=find(p[x]);
    }
    void unite(int a,int b){
        a=find(a); b=find(b);
        if(a==b) return;
        if(sz[a]<sz[b]) swap(a,b);
        p[b]=a;
        sz[a]+=sz[b];
    }
};

long long modpow(long long a, long long e){
    long long r=1%MOD;
    while(e){
        if(e&1) r=r*a%MOD;
        a=a*a%MOD;
        e>>=1;
    }
    return r;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long X, Y;
    cin >> N >> X >> Y;
    vector<long long> c(N), w(N);
    for(int i=0;i<N;i++) cin >> c[i] >> w[i];

    // Key fact:
    // Consider graph on balls, where an edge means those two balls can be swapped directly:
    // - same color and wi+wj <= X
    // - different color and wi+wj <= Y
    //
    // Since swaps along edges generate arbitrary permutations inside each connected component,
    // the obtainable color sequences are exactly all assignments of the multiset of colors
    // inside each connected component to the positions of that component.
    //
    // So answer = product over connected components:
    //   size(component)! / product_color(cnt_color!)  mod MOD

    // Build components efficiently.
    // Since X,Y are thresholds on sums, and X<=? not guaranteed relative to Y.
    // We use the following:
    // For different colors, edge if wi+wj<=Y.
    // For same color, edge if wi+wj<=max(X,Y?) No:
    // same-color edge exists if <=X; if also <=Y but colors same, op2 cannot be used.
    //
    // We need exact connectivity in this graph.
    //
    // Observation for threshold graph on weights:
    // among a set of vertices where edges exist for sum<=T, connected components can be found
    // after sorting by weight: consecutive vertices belong to same component iff there exists
    // a chain, which is equivalent to current minimum weight + current weight <= T.
    //
    // We'll compute:
    // 1) Components in graph GY formed by all pairs with wi+wj<=Y, regardless of color.
    //    But same-color pairs are not allowed there. So this is not exact.
    //
    // Better approach:
    // Split by color.
    // Different-color edges connect almost everything light enough.
    //
    // Let global weights sorted. For any ball i, it has diff-color edges to all balls of weight <= Y-wi
    // except same-color ones.
    // This means once a component contains at least two colors, it tends to absorb all sufficiently light balls.
    //
    // A simpler and correct O(N log N) approach:
    // Build components by BFS over intervals in weight order using DSU + color handling.
    //
    // However constraints are omitted here; we provide a robust O(N^2) fallback only if N moderate.
    // Since AtCoder-style problem likely has larger N, we need a stronger method.
    //
    // Strong observation:
    // If there exists at least one pair of different colors in a set S connected under <=Y,
    // then all vertices in the <=Y-threshold connected component of the underlying complete threshold graph
    // belong to one component of the actual graph, because same-color obstacles can be bypassed through
    // a vertex of another color.
    //
    // The only time a <=Y-threshold component splits is when it consists of a single color only.
    //
    // Therefore:
    // - Compute components of H_Y: complete graph edges wi+wj<=Y (ignoring colors).
    // - For each such component:
    //   * if it contains at least two distinct colors, then it is one actual component.
    //   * if all balls have same color col, actual edges are only same-color with threshold X,
    //     so it further splits according to threshold X within that color.
    //
    // This is correct because in a Y-component with >=2 colors, take a lightest ball m.
    // For any ball v in the Y-component, by definition there is a chain in H_Y.
    // Since m + every vertex in the component suffix condition holds inductively, and there exists
    // some vertex of different color reachable from m, same-color missing edges can be bypassed,
    // making the whole Y-component connected in actual graph.

    vector<int> ord(N);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int a, int b){
        if(w[a]!=w[b]) return w[a]<w[b];
        return a<b;
    });

    // Find components in H_Y on sorted weights.
    vector<int> compY(N, -1);
    int cidY = 0;
    int l = 0;
    while(l < N){
        int r = l;
        long long mn = w[ord[l]];
        while(r + 1 < N && mn + w[ord[r+1]] <= Y) r++;
        // Because mn stays the minimum in sorted order, this indeed gives maximal connected block.
        for(int k=l;k<=r;k++) compY[ord[k]] = cidY;
        cidY++;
        l = r + 1;
    }

    vector<vector<int>> groupsY(cidY);
    for(int i=0;i<N;i++) groupsY[compY[i]].push_back(i);

    DSU dsu(N);

    for(auto &grp : groupsY){
        unordered_map<long long, int> cnt;
        cnt.reserve(grp.size()*2+1);
        for(int v: grp) cnt[c[v]]++;

        if(cnt.size() >= 2){
            // whole group connected
            int root = grp[0];
            for(int i=1;i<(int)grp.size();i++) dsu.unite(root, grp[i]);
        }else{
            // single color only: split by threshold X
            vector<int> ids = grp;
            sort(ids.begin(), ids.end(), [&](int a, int b){
                if(w[a]!=w[b]) return w[a]<w[b];
                return a<b;
            });
            int l2 = 0, m = ids.size();
            while(l2 < m){
                int r2 = l2;
                long long mn = w[ids[l2]];
                while(r2 + 1 < m && mn + w[ids[r2+1]] <= X) r2++;
                int root = ids[l2];
                for(int k=l2+1;k<=r2;k++) dsu.unite(root, ids[k]);
                l2 = r2 + 1;
            }
        }
    }

    // Gather final components and color counts
    unordered_map<int, vector<int>> comps;
    comps.reserve(N*2+1);
    for(int i=0;i<N;i++) comps[dsu.find(i)].push_back(i);

    vector<long long> fact(N+1), invfact(N+1);
    fact[0]=1;
    for(int i=1;i<=N;i++) fact[i]=fact[i-1]*i%MOD;
    invfact[N]=modpow(fact[N], MOD-2);
    for(int i=N;i>=1;i--) invfact[i-1]=invfact[i]*i%MOD;

    long long ans = 1;
    for(auto &it : comps){
        auto &vec = it.second;
        unordered_map<long long,int> cc;
        cc.reserve(vec.size()*2+1);
        for(int v: vec) cc[c[v]]++;
        long long ways = fact[vec.size()];
        for(auto &p: cc) ways = ways * invfact[p.second] % MOD;
        ans = ans * ways % MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int X = Integer.parseInt(st.nextToken());
        int Y = Integer.parseInt(st.nextToken());

        int[] color = new int[N];
        int[] weight = new int[N];
        Map<Integer, List<Integer>> colorToIndices = new HashMap<>();

        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            color[i] = Integer.parseInt(st.nextToken());
            weight[i] = Integer.parseInt(st.nextToken());
            colorToIndices.computeIfAbsent(color[i], k -> new ArrayList<>()).add(i);
        }

        // DSU
        int[] parent = new int[N];
        int[] size = new int[N];
        for (int i = 0; i < N; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        // Union by weight order within same color
        for (List<Integer> indices : colorToIndices.values()) {
            indices.sort(Comparator.comparingInt(i -> weight[i]));
            for (int j = 1; j < indices.size(); j++) {
                int a = indices.get(j-1);
                int b = indices.get(j);
                if (weight[a] + weight[b] <= X) {
                    union(parent, size, a, b);
                }
            }
        }

        // Global minimum weight ball
        int minIdx = 0;
        for (int i = 1; i < N; i++) {
            if (weight[i] < weight[minIdx]) minIdx = i;
        }

        // For each color, get lightest ball index
        Map<Integer, Integer> colorLightest = new HashMap<>();
        for (int i = 0; i < N; i++) {
            int c = color[i];
            if (!colorLightest.containsKey(c) || weight[i] < weight[colorLightest.get(c)]) {
                colorLightest.put(c, i);
            }
        }

        // Union via operation 2: connect lightest of each color with global min if possible
        for (Map.Entry<Integer, Integer> entry : colorLightest.entrySet()) {
            int idx = entry.getValue();
            if (color[idx] != color[minIdx] && weight[idx] + weight[minIdx] <= Y) {
                union(parent, size, idx, minIdx);
            }
        }

        // Also connect lightest balls of different colors directly if sum ≤ Y
        List<Integer> lightestList = new ArrayList<>(colorLightest.values());
        for (int i = 0; i < lightestList.size(); i++) {
            for (int j = i+1; j < lightestList.size(); j++) {
                int a = lightestList.get(i);
                int b = lightestList.get(j);
                if (color[a] != color[b] && weight[a] + weight[b] <= Y) {
                    union(parent, size, a, b);
                }
            }
        }

        // Group by component root
        Map<Integer, Map<Integer, Integer>> compColorCount = new HashMap<>();
        for (int i = 0; i < N; i++) {
            int root = find(parent, i);
            compColorCount.computeIfAbsent(root, k -> new HashMap<>());
            Map<Integer, Integer> cc = compColorCount.get(root);
            cc.put(color[i], cc.getOrDefault(color[i], 0) + 1);
        }

        // Precompute factorials and inverse factorials
        long[] fact = new long[N+1];
        long[] invFact = new long[N+1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i-1] * i % MOD;
        invFact[N] = modPow(fact[N], MOD-2);
        for (int i = N-1; i >= 0; i--) invFact[i] = invFact[i+1] * (i+1) % MOD;

        long ans = 1;
        for (Map<Integer, Integer> cc : compColorCount.values()) {
            int compSize = 0;
            long ways = 1;
            for (int cnt : cc.values()) {
                compSize += cnt;
                ways = ways * invFact[cnt] % MOD;
            }
            ways = ways * fact[compSize] % MOD;
            ans = ans * ways % MOD;
        }

        System.out.println(ans);
    }

    static int find(int[] parent, int x) {
        if (parent[x] != x) parent[x] = find(parent, parent[x]);
        return parent[x];
    }

    static void union(int[] parent, int[] size, int a, int b) {
        int ra = find(parent, a);
        int rb = find(parent, b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            int tmp = ra; ra = rb; rb = tmp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }
}

