/*
Key idea:
A swap between positions i and j is possible iff the two balls currently there satisfy:
- same color and wi + wj <= X, or
- different colors and wi + wj <= Y.

We need the number of distinct color sequences reachable.

Observation:
Think of balls as vertices. Put an undirected edge between two balls if they can be swapped directly
(regardless of current positions; only depends on the two balls themselves).
Then by repeatedly swapping along edges, within each connected component of this graph, balls can be
permuted arbitrarily among the positions currently occupied by that component. Therefore, the only
invariant is, for each connected component, the multiset of colors inside it; and reachable color
sequences are exactly obtained by assigning to the positions of each component any arrangement of those colors.

So answer = product over connected components C of:
    |C|! / product_c (cnt_C[c]!)
mod MOD.

Thus we only need connected components of the graph.

Graph definition:
For balls i,j:
- if ci == cj: edge if wi + wj <= X
- else       : edge if wi + wj <= Y

Naively O(N^2) is impossible.

Crucial structure:
Sort by weight. For a fixed vertex i, neighbors are all vertices with weight <= threshold:
- threshold = X - wi among same color
- threshold = Y - wi among different colors

We process vertices in increasing weight, activating prior vertices whose weight is small enough.
Connected components are maintained by DSU.

To connect a new vertex i to all currently active eligible vertices efficiently:
- For "different colors": among all active vertices, connect i to one representative of every active DSU component
  that contains some active vertex of color != ci. Connecting to one vertex per such component is enough.
- For "same color": among active vertices of color ci, connect i to one representative of every active DSU component
  containing that color.

We need a data structure to enumerate all distinct active DSU roots in a set:
1) global active set
2) active set for each color

We use linked lists of members for each DSU root, and "next unprocessed" skipping pointers over the sorted order.
Each vertex is inserted into:
- global list
- color-specific list
When components merge, lists are concatenated small-to-large.

To enumerate distinct roots among active eligible vertices up to some threshold T:
we iterate active vertices in the corresponding list with index <= ptr(T), and for each encountered vertex v,
take r = find(v). If r not yet seen in this query, connect to v. We use query timestamps to deduplicate roots.
Total complexity is near O(N log N + total list traversals amortized by DSU small-to-large), acceptable.

After building components, count colors in each component and multiply multinomial counts.
*/

public class Main {
    static final long MOD = 1_000_000_007L;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Ball {
        int idx;
        int color;
        long w;
        int ord;
    }

    static int N;
    static long X, Y;
    static Ball[] balls;
    static int[] colorCompressed;

    // DSU
    static int[] parent, size;

    // linked list of vertices in each DSU root (global members)
    static int[] head, tail, nextInComp;

    static int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static int union(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return a;
        if (size[a] < size[b]) {
            int t = a; a = b; b = t;
        }
        parent[b] = a;
        size[a] += size[b];

        // concatenate member list
        nextInComp[tail[a]] = head[b];
        tail[a] = tail[b];
        return a;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();
        X = fs.nextLong();
        Y = fs.nextLong();

        int[] c = new int[N];
        long[] w = new long[N];
        for (int i = 0; i < N; i++) {
            c[i] = fs.nextInt();
            w[i] = fs.nextLong();
        }

        // compress colors
        int[] cc = c.clone();
        Arrays.sort(cc);
        int m = 0;
        for (int i = 0; i < N; i++) {
            if (i == 0 || cc[i] != cc[i - 1]) cc[m++] = cc[i];
        }
        colorCompressed = new int[N];
        for (int i = 0; i < N; i++) {
            colorCompressed[i] = Arrays.binarySearch(cc, 0, m, c[i]);
        }

        balls = new Ball[N];
        for (int i = 0; i < N; i++) {
            balls[i] = new Ball();
            balls[i].idx = i;
            balls[i].color = colorCompressed[i];
            balls[i].w = w[i];
        }

        Arrays.sort(balls, Comparator.comparingLong(b -> b.w));
        for (int i = 0; i < N; i++) balls[i].ord = i;

        // DSU init
        parent = new int[N];
        size = new int[N];
        head = new int[N];
        tail = new int[N];
        nextInComp = new int[N];
        Arrays.fill(nextInComp, -1);
        for (int i = 0; i < N; i++) {
            parent[i] = i;
            size[i] = 1;
            head[i] = tail[i] = i;
        }

        // active lists by weight order
        ArrayList<Integer>[] byColor = new ArrayList[m];
        for (int i = 0; i < m; i++) byColor[i] = new ArrayList<>();
        ArrayList<Integer> global = new ArrayList<>();
        for (int ord = 0; ord < N; ord++) {
            int idx = balls[ord].idx;
            global.add(idx);
            byColor[balls[ord].color].add(idx);
        }

        // For threshold queries, use upper_bound on sorted weights globally and per color via stored ord lists
        long[] sortedW = new long[N];
        for (int i = 0; i < N; i++) sortedW[i] = balls[i].w;

        // per color sorted weights/vertices
        long[][] colorWeights = new long[m][];
        int[][] colorVerts = new int[m][];
        for (int col = 0; col < m; col++) {
            int sz = byColor[col].size();
            colorWeights[col] = new long[sz];
            colorVerts[col] = new int[sz];
            for (int j = 0; j < sz; j++) {
                int idx = byColor[col].get(j);
                colorWeights[col][j] = w[idx];
                colorVerts[col][j] = idx;
            }
        }

        int[] seenRoot = new int[N];
        int[] seenColorInRoot = new int[N];
        int timer = 1;

        // Build edges implicitly by connecting each vertex to representatives of all eligible active components.
        // Since only earlier/lighter vertices matter, process in increasing weight.
        for (int ord = 0; ord < N; ord++) {
            int i = balls[ord].idx;
            int col = colorCompressed[i];
            long wi = w[i];

            // same color eligible earlier vertices: weight <= X - wi
            long tSame = X - wi;
            if (tSame >= 0) {
                int lim = upperBound(colorWeights[col], tSame) - 1;
                while (lim >= 0 && colorVerts[col][lim] == i) lim--; // exclude self if included
                if (lim >= 0) {
                    timer++;
                    for (int p = 0; p <= lim; p++) {
                        int v = colorVerts[col][p];
                        if (v == i) continue;
                        int r = find(v);
                        if (seenRoot[r] != timer) {
                            seenRoot[r] = timer;
                            union(i, v);
                        }
                    }
                }
            }

            // different color eligible earlier vertices: weight <= Y - wi
            long tDiff = Y - wi;
            if (tDiff >= 0) {
                int lim = upperBound(sortedW, tDiff) - 1;
                while (lim >= 0 && balls[lim].idx == i) lim--; // exclude self if included
                if (lim >= 0) {
                    timer++;
                    int rootIColor = find(i);
                    for (int p = 0; p <= lim; p++) {
                        int v = balls[p].idx;
                        if (v == i) continue;
                        if (colorCompressed[v] == col) continue;
                        int r = find(v);
                        if (seenRoot[r] != timer) {
                            seenRoot[r] = timer;
                            union(i, v);
                        }
                    }
                }
            }
        }

        // factorials
        long[] fact = new long[N + 1];
        long[] invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[N] = modPow(fact[N], MOD - 2);
        for (int i = N; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;

        // collect component color counts
        HashMap<Integer, HashMap<Integer, Integer>> compMap = new HashMap<>();
        for (int i = 0; i < N; i++) {
            int r = find(i);
            HashMap<Integer, Integer> mp = compMap.get(r);
            if (mp == null) {
                mp = new HashMap<>();
                compMap.put(r, mp);
            }
            mp.put(colorCompressed[i], mp.getOrDefault(colorCompressed[i], 0) + 1);
        }

        long ans = 1;
        for (Map.Entry<Integer, HashMap<Integer, Integer>> e : compMap.entrySet()) {
            int r = e.getKey();
            ans = ans * fact[size[find(r)]] % MOD;
            for (int cnt : e.getValue().values()) {
                ans = ans * invFact[cnt] % MOD;
            }
        }

        System.out.println(ans % MOD);
    }

    static int upperBound(long[] a, long x) {
        int l = 0, r = a.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a[mid] <= x) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }
}

